using System; using System.Collections.Generic; using System.Globalization; using System.Linq; using System.Security.Cryptography; using System.Text;
namespace CollegePortal.FisGatewayAgent { public class SecurityValidator { private readonly GatewayConfig _config; private readonly NonceStore _nonceStore; private readonly RateLimiter _rateLimiter; public SecurityValidator(GatewayConfig config, NonceStore nonceStore, RateLimiter rateLimiter){ _config=config; _nonceStore=nonceStore; _rateLimiter=rateLimiter; }
public ValidationResult Validate(string method,string path,string remoteIp,IDictionary<string,string> headers,byte[] body,bool requireSignature){ if(_config.AllowedPortalIps.Length>0&&!_config.AllowedPortalIps.Contains(remoteIp)) return ValidationResult.Fail("ip_denied","IP address is not allowlisted."); if(!_rateLimiter.Allow(remoteIp)) return ValidationResult.Fail("rate_limited","Too many requests."); if(body!=null&&body.Length>_config.MaxBodyBytes) return ValidationResult.Fail("request_too_large","Request body is too large."); if(!requireSignature) return ValidationResult.Ok(); var required=new[]{"X-FIS-Timestamp","X-FIS-Nonce","X-FIS-Body-SHA256","X-FIS-Signature","X-FIS-Request-Id"}; foreach(var h in required) if(!headers.ContainsKey(h)||string.IsNullOrEmpty(headers[h])) return ValidationResult.Fail("auth_required","Missing HMAC headers."); DateTime ts; if(!DateTime.TryParseExact(headers["X-FIS-Timestamp"],"yyyy-MM-ddTHH:mm:ssZ",CultureInfo.InvariantCulture,DateTimeStyles.AssumeUniversal|DateTimeStyles.AdjustToUniversal,out ts)) return ValidationResult.Fail("invalid_timestamp","Timestamp format is invalid."); if(Math.Abs((DateTime.UtcNow-ts).TotalSeconds)>_config.RequestWindowSeconds) return ValidationResult.Fail("expired_timestamp","Request timestamp is outside allowed window."); var bodyHash=HexSha256(body??new byte[0]); if(!ConstantTimeEquals(bodyHash,headers["X-FIS-Body-SHA256"])) return ValidationResult.Fail("body_hash_mismatch","Body SHA-256 does not match."); if(!_nonceStore.TryUse(headers["X-FIS-Nonce"],ts)) return ValidationResult.Fail("reused_nonce","Nonce was already used."); var canonical=method.ToUpperInvariant()+"\n"+path+"\n"+headers["X-FIS-Timestamp"]+"\n"+headers["X-FIS-Nonce"]+"\n"+bodyHash; var expected=Hmac(canonical,_config.SharedSecret??""); if(!ConstantTimeEquals(expected,headers["X-FIS-Signature"])) return ValidationResult.Fail("invalid_hmac","HMAC signature is invalid."); return ValidationResult.Ok(); }
public static string HexSha256(byte[] bytes){ using(var sha=SHA256.Create()) return BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-","").ToLowerInvariant(); } public static string Hmac(string canonical,string secret){ using(var hmac=new HMACSHA256(Encoding.UTF8.GetBytes(secret))) return Convert.ToBase64String(hmac.ComputeHash(Encoding.UTF8.GetBytes(canonical))); } public static bool ConstantTimeEquals(string a,string b){ var aa=Encoding.UTF8.GetBytes(a??""); var bb=Encoding.UTF8.GetBytes(b??""); var diff=aa.Length^bb.Length; for(var i=0;i<Math.Min(aa.Length,bb.Length);i++) diff|=aa[i]^bb[i]; return diff==0; }} public class ValidationResult{ public bool Success; public string Code; public string Message; public static ValidationResult Ok(){return new ValidationResult{Success=true};} public static ValidationResult Fail(string code,string message){return new ValidationResult{Success=false,Code=code,Message=message};}}}
